function list(ref: string) {
  return {
    type: "object",
    properties: {
      object: { type: "string", enum: ["list"] },
      data: { type: "array", items: { $ref: `#/components/schemas/${ref}` } },
    },
  };
}

/** `next_offset`: the same token as `next_cursor`, present only while `has_more`. */
const nextOffsetProp = {
  type: "string",
  description: "Present only while has_more; the same opaque token as next_cursor — pass as offset",
};

/**
 * A cursor-paginated list (docs/GUIDE.md §3.4). `next_cursor` is OPAQUE — pass it
 * back as `starting_after` (or `next_offset` as `offset`). `total` is the filtered count
 * and is only present on the first page.
 */
function pagedList(ref: string) {
  return {
    type: "object",
    properties: {
      object: { type: "string", enum: ["list"] },
      data: { type: "array", items: { $ref: `#/components/schemas/${ref}` } },
      has_more: { type: "boolean" },
      next_cursor: {
        type: "string",
        nullable: true,
        description: "Opaque; pass as starting_after",
      },
      next_offset: nextOffsetProp,
      total: {
        type: "integer",
        nullable: true,
        description: "Filtered-set count; first page only",
      },
    },
  };
}

/**
 * ── `field[op]=value` IS THE WIRE FORM; `filters=` IS NOT A PARAMETER (2026-09-02) ──
 *
 * This document used to declare ONE query parameter literally named `filters`, whose
 * description spelled the real grammar out in prose "because OpenAPI 3.0 can't express
 * templated parameter names". Both halves of that cost us:
 *
 *  · The machine-readable half was false. `parseListQuery` (src/api/helpers.ts) refuses
 *    any bare key that is not reserved or route-declared, so every client generated from
 *    this document offered a `filters` argument whose only possible outcome was
 *    `400 Unknown query parameter 'filters'`. It was found by running the published spec
 *    against a live API, not by reading it — which is the only way this kind of lie shows.
 *  · The prose half drifted, exactly as the hand-copied email-type list had: it named 13
 *    of the invoice list's 33 filterable fields, 4 of its 9 sort keys and 5 of the 9 text
 *    operators, while referencing fields (`created_at`, `number`, `customer`) that the
 *    `Invoice` component then denied existed.
 *
 * OpenAPI 3.1 CAN express this. A `deepObject` object-valued parameter named for the
 * FIELD serialises as `field[op]=value` — `created_at[after]=2026-09-01`, byte for byte
 * what the engine parses — so every filterable field is now its own real parameter, its
 * operators the object's properties, generated from the field's KIND.
 *
 * `FILTER_OPS_BY_KIND` mirrors `OPS_BY_KIND` in `src/platform/list-query.ts`, and each
 * endpoint's field table mirrors that module's `*_FILTER_OPS`. This document stays
 * import-free on purpose (scripts and unit tests load it without dragging in the DB
 * layer), so those are hand copies — and a hand copy is only honest while a test asserts
 * it: `test/unit/openapi-filters.test.ts` compares the documented fields, operators and
 * sort keys against the real maps and fails on drift, the same guard the `EMAIL_TYPES`
 * mirror needed after it had drifted to 5 of 25 types.
 */
const FILTER_OPS_BY_KIND = {
  text: [
    "is",
    "is_not",
    "contains",
    "not_contains",
    "starts_with",
    "ends_with",
    "in",
    "not_in",
    "is_present",
  ],
  enum: ["is", "is_not", "in", "not_in", "is_present"],
  bool: ["is"],
  number: ["is", "is_not", "gt", "gte", "lt", "lte", "between", "is_present"],
  date: [
    "on",
    "before",
    "after",
    "on_or_before",
    "on_or_after",
    "between",
    "in_last",
    "in_next",
    "is_present",
  ],
} as const;

/** `field → kind`, or an explicit operator list for a virtual (EXISTS-backed) field. */
type FilterFields = Record<string, keyof typeof FILTER_OPS_BY_KIND | readonly string[]>;

/**
 * The VALUE grammar per operator, stated once and attached to every filter's operator
 * properties. Mirrors `filterValueError` / `splitMulti` in `src/platform/list-query.ts`.
 */
const SET_VALUE = 'Comma-separated (`a,b`) or a JSON array (`["a","b"]`).';
const DAY_VALUE = "`YYYY-MM-DD` (a whole business-zone day)";
const INSTANT_VALUE = "unix seconds (an exact instant)";
function opValueDescription(kind: string | null, op: string): string | undefined {
  if (op === "in" || op === "not_in") return SET_VALUE;
  if (op === "is_present") return "`true` or `false`.";
  if (op === "in_last" || op === "in_next") return "A positive number of days.";
  if (op === "between") {
    return kind === "date"
      ? `Two bounds, inclusive: ${SET_VALUE} Each bound is ${DAY_VALUE} or ${INSTANT_VALUE}.`
      : `Two bounds, inclusive: ${SET_VALUE}`;
  }
  if (kind === "date" && op === "on") {
    return `${DAY_VALUE}, or unix seconds — the business-zone day containing that instant.`;
  }
  if (kind === "date") return `${DAY_VALUE}, or ${INSTANT_VALUE}.`;
  return undefined;
}

/**
 * One `deepObject` parameter per filterable field, which is how `field[op]=value`
 * reaches the wire. `additionalProperties: false` is what makes a generated client
 * refuse an operator the route would 400 on.
 */
function filterParams(fields: FilterFields, notes: Record<string, string> = {}) {
  return Object.entries(fields).map(([field, spec]) => {
    const ops = typeof spec === "string" ? FILTER_OPS_BY_KIND[spec] : spec;
    const kind = typeof spec === "string" ? spec : null;
    return {
      name: field,
      in: "query",
      required: false,
      style: "deepObject",
      explode: true,
      schema: {
        type: "object",
        additionalProperties: false,
        properties: Object.fromEntries(
          ops.map((op) => {
            const description = opValueDescription(kind, op);
            return [op, { type: "string", ...(description ? { description } : {}) }];
          }),
        ),
      },
      ...(notes[field] ? { description: notes[field] } : {}),
    };
  });
}

/**
 * The query params shared by every paginated list: the reserved four, then one
 * parameter per filterable field (see `filterParams`).
 */
function listParams(opts: {
  sortFields: readonly string[];
  /** The endpoint's filterable fields — each becomes its own `field[op]` parameter. */
  filters: FilterFields;
  /** Per-field prose, rendered as that field's parameter description. */
  filterNotes?: Record<string, string>;
  search: string;
  /** What `include_deleted=true` does on this list (mirrors the route's `includeDeleted`). */
  includeDeleted?: string;
}) {
  return [
    {
      name: "limit",
      in: "query",
      required: false,
      schema: { type: "integer", default: 50, minimum: 1, maximum: 1000 },
    },
    {
      name: "starting_after",
      in: "query",
      required: false,
      schema: { type: "string" },
      description: "Opaque cursor from a previous next_cursor",
    },
    {
      name: "offset",
      in: "query",
      required: false,
      schema: { type: "string" },
      description:
        "The previous page's next_offset — the same token as next_cursor under a second name. Pass one of offset or starting_after, not two different values.",
    },
    ...(opts.includeDeleted
      ? [
          {
            name: "include_deleted",
            in: "query",
            required: false,
            schema: { type: "boolean", default: false },
            description: opts.includeDeleted,
          },
        ]
      : []),
    {
      name: "q",
      in: "query",
      required: false,
      schema: { type: "string" },
      description: opts.search,
    },
    {
      name: "sort_by[asc]",
      in: "query",
      required: false,
      schema: { type: "string", enum: opts.sortFields },
    },
    {
      name: "sort_by[desc]",
      in: "query",
      required: false,
      schema: { type: "string", enum: opts.sortFields },
    },
    ...filterParams(opts.filters, opts.filterNotes),
  ];
}

/**
 * `listParams` for a list that returns its WHOLE (filtered) set unless the caller pages.
 */
function optInListParams(opts: Parameters<typeof listParams>[0]) {
  return listParams(opts).map((p) =>
    p.name === "limit"
      ? {
          ...p,
          schema: { type: "integer", minimum: 1, maximum: 1000 },
          description:
            "Opt-in paging. Without `limit` or `starting_after` every matching row is returned " +
            "as `{ object, data }`; `q`, `sort_by` and `field[op]` filters apply either way. " +
            "With either, the response is one page with `has_more`, `next_cursor` and `total` " +
            "(`limit` defaults to 50).",
        }
      : p,
  );
}

const pathParam = (name: string) => ({
  name,
  in: "path",
  required: true,
  schema: { type: "string" },
});

const idempotencyHeader = {
  name: "Idempotency-Key",
  in: "header",
  required: false,
  schema: { type: "string" },
  /**
   * ⚠️ The second sentence is the one that was missing, and its absence was filed as a
   * defect (#47) before being traced here. "Repeats return the original response" is true
   * but incomplete in the case that matters: when a request FAILED after it had already
   * written something — a 5xx raised once the gateway had been asked — the stored
   * response is that FAILURE, and replaying it is deliberate. `idempotencyOnSend` records
   * `failed` rather than dropping the row precisely because dropping it made the client's
   * retry RE-EXECUTE, which on a billing path charges twice.
   *
   * So a caller retrying the same key after such a failure gets the failure back forever,
   * which reads like a stuck endpoint unless the contract says otherwise. It now says so:
   * the key is spent, and a fresh attempt needs a fresh key. (Where NOTHING durable was
   * written the row is deleted instead, so that key is not spent and a plain retry is
   * free — the caller does not have to know which case they were in, only that a new key
   * always works.)
   */
  description:
    "Safely retry writes — repeats return the original response. If a write FAILED after " +
    "it had already taken effect, that failure is what repeats: the key is spent, and a " +
    "new attempt needs a new key.",
};

