          content: {
            "application/json": {
              schema: {
                type: "object",
                properties: {
                  trial_end: {
                    type: "string",
                    format: "date-time",
                    description: "New future trial end date",
                  },
                  immediately: {
                    type: "boolean",
                    description:
                      "End the trial now — activates the subscription and bills the first term",
                  },
                },
              },
            },
          },
