type FieldCtx = {
  kind: "S" | "O";
  owners: string[];
  method: string;
  rel: string;
  trail: string;
  leaf: string;
  noun: string;
  pnoun: string;
  prefix: string;
};

const ID_PREFIXES: Record<string, string> = {
  Organization: "org_",
  Business: "biz_",
  Customer: "cus_",
  Subscription: "sub_",
  Invoice: "inv_",
  CreditNote: "cn_",
  Product: "prod_",
  ProductGroup: "pgrp_",
  Price: "price_",
  Coupon: "cpn_",
  CouponSet: "cpset_",
  Transaction: "txn_",
  PaymentMethod: "pm_",
  PaymentIntent: "pi_",
  PaymentAttempt: "pia_",
  Refund: "re_",
  CustomFieldDefinition: "cfd_",
  MetadataKeyRule: "mkr_",
  ListView: "lv_",
  ApiKey: "key_",
  Role: "role_",
  Feature: "feat_",
  WebhookEndpoint: "whe_",
  TaxProfile: "txp_",
  TaxRegion: "txg_",
  TaxRateComponent: "txc_",
  TaxStateRegistration: "txs_",
  CustomerSegment: "seg_",
};

const words = (s: string) =>
  s
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/_/g, " ")
    .replace(/([a-z])(\d)/g, "$1 $2")
    .toLowerCase()
    .replace("hub spot", "HubSpot");
const singular = (s: string) =>
  s
    .replace(/ies$/, "y")
    .replace(/(ss|us)$/, "$1")
    .replace(/(?<!s)s$/, "")
    .replace(/ses$/, "s");

function fieldRuleMatches(rule: string, ctx: FieldCtx): boolean {
  const trailIs = (p: string) => ctx.trail === p || ctx.trail.endsWith("." + p);
  if (rule.startsWith("OP ")) {
    const [, method, path, trail] = rule.split(" ");
    return ctx.kind === "O" && ctx.method === method && ctx.rel === path && trailIs(trail ?? "");
  }
  if (rule.startsWith("RE:")) return new RegExp(rule.slice(3)).test(ctx.leaf);
  if (rule.startsWith("PARAM:")) return ctx.trail === rule;
  if (rule.includes(" ")) {
    const [owner, trail] = rule.split(" ");
    return (
      ctx.kind === "S" &&
      ctx.owners.includes(owner ?? "") &&
      ctx.trail.replace(/^data\./, "") === trail
    );
  }
  return !ctx.trail.startsWith("PARAM:") && trailIs(rule);
}

const fieldRank = (rule: string) =>
  rule.startsWith("OP ")
    ? 0
    : rule.startsWith("RE:")
      ? 4
      : rule.includes(" ")
        ? 1
        : rule.includes(".") || rule.startsWith("PARAM:")
          ? 2
          : 3;
const FIELD_RULES_ORDERED = FIELD_RULES.map((r, i) => ({ r, i })).sort(
  (a, b) => fieldRank(a.r[0]) - fieldRank(b.r[0]) || a.i - b.i,
);

function fieldText(ctx: FieldCtx, node: Record<string, unknown>): string {
  if (ctx.leaf === "object") {
    const en = node.enum as string[] | undefined;
    return en?.length === 1 ? `The object type; always \`${en[0]}\`.` : "The object type.";
  }
  let text: string | undefined;
  let groups: RegExpExecArray | null = null;
  for (const { r } of FIELD_RULES_ORDERED) {
    if (node.style === "deepObject" && !r[0].startsWith("OP ")) continue;
    if (!fieldRuleMatches(r[0], ctx)) continue;
    text = r[1];
    if (r[0].startsWith("RE:")) groups = new RegExp(r[0].slice(3)).exec(ctx.leaf);
    break;
  }
  const label = words(ctx.leaf);
  if (!text) {
    if (node.style === "deepObject") {
      return `Filter on \`${ctx.leaf}\`. Send as \`${ctx.leaf}[<operator>]=<value>\`.`;
    }
    return ctx.kind === "S" ? `The ${ctx.noun}'s ${label}.` : `The ${label}.`;
  }
  return text
    .replace(/\{noun\}/g, ctx.noun)
    .replace(/\{pnoun\}/g, ctx.pnoun)
    .replace(/\{label\}/g, label)
    .replace(/\{prefix\}/g, ctx.prefix)
    .replace(/\{\$1\}/g, groups ? words(groups[1] ?? label) : label);
}

type DocNode = Record<string, unknown> & {
  properties?: Record<string, DocNode>;
  items?: DocNode;
  additionalProperties?: unknown;
};

let fieldSchemas: Record<string, DocNode> = {};
const refHasDescription = (ref: unknown) =>
  typeof ref === "string" && !!fieldSchemas[ref.replace("#/components/schemas/", "")]?.description;

function describeSchema(
  schema: DocNode | undefined,
  base: Omit<FieldCtx, "trail" | "leaf" | "noun">,
  trail: string[],
  baseNoun: string,
) {
  if (!schema || typeof schema !== "object" || schema.$ref) return;
  for (const c of ["allOf", "anyOf", "oneOf"] as const) {
    for (const part of (schema[c] as DocNode[] | undefined) ?? []) {
      describeSchema(part, base, trail, baseNoun);
    }
  }
  for (const [name, prop] of Object.entries(schema.properties ?? {})) {
    if (!prop || typeof prop !== "object") continue;
    const path = [...trail, name];
    if (!prop.description && !(prop.$ref && refHasDescription(prop.$ref))) {
      const parent = trail.filter((t) => t !== "data" && !/^(body|resp\d+)$/.test(t)).pop();
      prop.description = fieldText(
        {
          ...base,
          trail: path.join("."),
          leaf: name,
          noun: parent ? words(singular(parent)) : baseNoun,
        },
        prop,
      );
    }
    describeSchema(prop, base, path, baseNoun);
  }
  if (schema.items) describeSchema(schema.items, base, trail, baseNoun);
  if (schema.additionalProperties && typeof schema.additionalProperties === "object") {
    describeSchema(schema.additionalProperties as DocNode, base, trail, baseNoun);
  }
}

function withFieldDescriptions(spec: typeof openapiSpec): typeof openapiSpec {
  const doc = JSON.parse(JSON.stringify(spec)) as {
    components: { schemas: Record<string, DocNode> };
    paths: Record<string, Record<string, Record<string, unknown>>>;
  };
  fieldSchemas = doc.components.schemas;
  for (const [name, schema] of Object.entries(doc.components.schemas)) {
    const family = name.match(/^(PaymentIntent|PaymentAttempt)/)?.[1];
    const noList = name.replace(/List$/, "");
    const owners = [
      name,
      noList,
      noList.replace(/(Create|Update)$/, ""),
      ...(family ? [family] : []),
    ];
    const noun = words((family ?? noList).replace(/(Create|Update)$/, ""));
    describeSchema(
      schema,
      {
        kind: "S",
        owners,
        method: "",
        rel: "",
        pnoun: noun,
        prefix: ID_PREFIXES[family ?? noList] ? ` (${ID_PREFIXES[family ?? noList]}…)` : "",
      },
      [],
      noun,
    );
  }
  for (const [path, ops] of Object.entries(doc.paths)) {
    const rel = path.replace(/^\/v1\/businesses\/\{biz\}/, "").replace(/^\/v1/, "") || "/";
    const statics = rel.split("/").filter((s) => s && !s.startsWith("{"));
    const segs = rel.split("/").filter(Boolean);
    for (const [method, op] of Object.entries(ops)) {
      if (!op || typeof op !== "object") continue;
      const upper = method.toUpperCase();
      const noun = words(singular(statics[statics.length - 1] ?? "business"));
      const base = {
        kind: "O" as const,
        owners: [],
        method: upper,
        rel,
        pnoun: noun,
        prefix: "",
      };
      for (const p of (op.parameters as DocNode[] | undefined) ?? []) {
        if (!p || p.$ref || p.description) continue;
        const name = String(p.name);
        const at = segs.indexOf(`{${name}}`);
        const pnoun = words(singular((at > 0 ? segs[at - 1] : segs[0]) ?? name));
        p.description = fieldText(
          { ...base, pnoun, trail: `PARAM:${name}`, leaf: name, noun: pnoun },
          p as DocNode,
        );
      }
      const body = (op.requestBody as DocNode | undefined)?.content as
        | Record<string, { schema?: DocNode }>
        | undefined;
      for (const media of Object.values(body ?? {}))
        describeSchema(media.schema, base, ["body"], noun);
      for (const [code, resp] of Object.entries((op.responses as Record<string, DocNode>) ?? {})) {
        const content = resp?.content as Record<string, { schema?: DocNode }> | undefined;
        for (const media of Object.values(content ?? {})) {
          describeSchema(media.schema, base, [`resp${code}`], noun);
        }
      }
    }
  }
  return doc as unknown as typeof openapiSpec;
}
// </field-docs>

/**
 * Response bodies for operations whose handler returns a body the hand-written paths above
 * left undocumented. `withResponseSchemas` attaches each one to its operation and registers
 * the component schemas; an operation that already documents a body is never overwritten.
 */
const str = (description: string, extra: Record<string, unknown> = {}) => ({
  type: "string",
  description,
  ...extra,
});
const nstr = (description: string, extra: Record<string, unknown> = {}) =>
  str(description, { nullable: true, ...extra });
const int = (description: string, extra: Record<string, unknown> = {}) => ({
  type: "integer",
  description,
  ...extra,
});
const nint = (description: string, extra: Record<string, unknown> = {}) =>
  int(description, { nullable: true, ...extra });
const bool = (description: string) => ({ type: "boolean", description });
const dt = (description: string, nullable = false) => ({
  type: "string",
  format: "date-time",
  description,
  ...(nullable ? { nullable: true } : {}),
});
const rref = (name: string) => ({ $ref: `#/components/schemas/${name}` });
const arrOf = (items: unknown, description: string) => ({ type: "array", items, description });
const obj = (
  description: string,
  properties: Record<string, unknown>,
  required?: string[],
  extra: Record<string, unknown> = {},
) => ({ type: "object", description, ...(required ? { required } : {}), properties, ...extra });
const objectTag = (name: string) => ({
  type: "string",
  enum: [name],
  description: `The object type; always \`${name}\`.`,
});
const listOf = (ref: string, description: string, extra: Record<string, unknown> = {}) =>
  obj(
    description,
    {
      object: objectTag("list"),
      data: arrOf(rref(ref), "The items."),
      ...extra,
    },
    ["object", "data"],
  );
const pagedOf = (ref: string, description: string) =>
  listOf(ref, description, {
    has_more: bool("True if more items follow this page."),
    next_cursor: nstr("Opaque cursor; pass it as `starting_after` to read the next page."),
    next_offset: nextOffsetProp,
    total: nint("Count of the filtered set. First page only."),
  });
const deletedOf = (object: string, idDescription: string, description: string, extra = {}) =>
  obj(
    description,
    {
      object: objectTag(object),
      id: str(idDescription),
      deleted: bool("Always true."),
      ...extra,
    },
    ["object", "id", "deleted"],
  );
const refBox = (description: string, properties: Record<string, unknown>) =>
  obj(description, properties, ["id"], { nullable: true });
const docRef = (what: string) =>
  refBox(`The ${what} that the change raised, or null if it raised none.`, {
    id: str(`The ${what}'s id.`, {
      example: what === "invoice" ? "inv_XXXXXXXXXXXX01" : "cn_XXXXXXXXXXXX01",
    }),
    status: str(`The ${what}'s status.`, { example: what === "invoice" ? "paid" : "refunded" }),
    total_minor: int(`The ${what}'s total, in minor units.`, { example: 4900 }),
  });
const movementMoney = obj("Amounts in minor units, one entry per currency.", {}, undefined, {
  additionalProperties: { type: "integer" },
});

const mrrKpi = obj("A figure with its value in the previous period.", {
  value: int("The value for the selected period, in minor units or a count.", { example: 1250000 }),
  prev_value: int("The value for the previous period.", { example: 1180000 }),
  change_bps: nint(
    "Change from the previous period, in basis points. Null when the previous value is zero.",
    { example: 593 },
  ),
});

