/** Attach `RESPONSE_BINDINGS` to the operations that have no body schema yet. */
function withResponseSchemas(spec: typeof openapiSpec): typeof openapiSpec {
  const doc = structuredClone(spec) as unknown as {
    components: { schemas: Record<string, unknown> };
    paths: Record<string, Record<string, { responses?: Record<string, { content?: unknown }> }>>;
  };
  for (const [name, schema] of Object.entries(RESPONSE_COMPONENTS)) {
    if (doc.components.schemas[name])
      throw new Error(`openapi: component ${name} is already defined`);
    doc.components.schemas[name] = schema;
  }
  for (const [key, status, schema] of RESPONSE_BINDINGS) {
    const [method, path] = key.split(" ") as [string, string];
    const response = doc.paths[path]?.[method]?.responses?.[status];
    if (!response) throw new Error(`openapi: no ${status} response for ${key}`);
    if (response.content) throw new Error(`openapi: ${key} ${status} already documents a body`);
    response.content = { "application/json": { schema } };
  }
  return doc as unknown as typeof openapiSpec;
}

