type ExampleNode = Record<string, unknown> & {
  properties?: Record<string, ExampleNode>;
  items?: ExampleNode;
  additionalProperties?: unknown;
};

function withPropertyExamples(spec: typeof openapiSpec): typeof openapiSpec {
  const doc = structuredClone(spec) as unknown as {
    components: { schemas: Record<string, ExampleNode> };
  };
  const walk = (node: ExampleNode | undefined, owner: string, trail: string) => {
    if (!node || typeof node !== "object") return;
    for (const c of ["allOf", "anyOf", "oneOf"] as const) {
      for (const part of (node[c] as ExampleNode[] | undefined) ?? []) walk(part, owner, trail);
    }
    for (const [name, prop] of Object.entries(node.properties ?? {})) {
      if (!prop || typeof prop !== "object") continue;
      const key = `${owner}.${trail}${name}`;
      if (key in PROPERTY_EXAMPLES && prop.example === undefined && prop.enum === undefined) {
        prop.example = PROPERTY_EXAMPLES[key];
      }
      walk(prop, owner, `${trail}${name}.`);
    }
    if (node.items) walk(node.items, owner, trail);
    if (node.additionalProperties && typeof node.additionalProperties === "object") {
      walk(node.additionalProperties as ExampleNode, owner, trail);
    }
  };
  for (const [name, schema] of Object.entries(doc.components.schemas)) walk(schema, name, "");
  return doc as unknown as typeof openapiSpec;
}

export const openapiDocument = withFieldDescriptions(
  withPropertyExamples(withResponseSchemas(withIdempotencyDocs(openapiSpec))),
);
